pub fn check_operation_gate(
    case_space: &CaseSpace,
    gate: &NativeOperationGate,
    expected_operation: &str,
) -> Result<(), NativeOperationGateError> {
    let failures = operation_gate_failures(case_space, gate, expected_operation);
    if failures.is_empty() {
        return Ok(());
    }
    // The expected value is withheld everywhere or nowhere.
    //
    // Two separate questions, and they were run together once already. The
    // first is whether naming the value is *honest*: on a case space that
    // fails the evaluability contract, retrying with it passes this gate and
    // dies at the append with `store_integrity`, forever -- so the value is
    // named nowhere, not in the message, not in `witness_ids`, not in
    // `field_mismatches`. Suppressing only the structured field left the
    // value copyable from the other two, out of a refusal that simultaneously
    // said no value was on offer.
    //
    // The second is whether the caller should be *told to retry*: that needs
    // every clause to be mechanical, because a refusal that also failed on
    // capability or actor is an escalation, not a correction. A mixed refusal
    // over an evaluable space still names the value -- it is true, and it is
    // readable ungated anyway -- but withholds `field_mismatches`.
    //
    // The validator runs only when a mismatch is present, so a passing gate
    // and a pure authority refusal never pay for the walk.
    let mismatches = failures
        .iter()
        .filter_map(|failure| failure.as_mismatch().cloned())
        .collect::<Vec<_>>();
    let reveal_expected = !mismatches.is_empty()
        && crate::native_eval::validate_native_case_space(case_space).is_ok();
    let witness_ids = failures
        .iter()
        .flat_map(|failure| failure.witness_ids(reveal_expected))
        .collect();
    let labels = failures
        .iter()
        .map(|failure| failure.message(reveal_expected))
        .collect::<Vec<_>>()
        .join("; ");
    let all_mechanical = mismatches.len() == failures.len();
    let any_mismatch = !mismatches.is_empty();
    let field_mismatches = if reveal_expected && all_mechanical {
        mismatches
    } else {
        Vec::new()
    };
    let evaluability_note = if any_mismatch && !reveal_expected {
        "; no expected value is offered because this case space does not satisfy the store's \
         evaluability contract, so retrying with it would pass this gate and then be refused \
         when the mutation is appended — this state should be investigated rather than retried"
    } else {
        ""
    };
    Err(NativeOperationGateError {
        message: format!(
            "operation gate for {expected_operation:?} violates: {labels}{evaluability_note}"
        ),
        witness_ids,
        field_mismatches,
    })
}

fn policy_capability_gate_invariant(
    case_space: &CaseSpace,
    request: &NativeCloseCheckRequest,
) -> NativeCloseInvariantResult {
    let has_close_policy =
        request.close_policy_id.is_some() || case_space.close_policy_id.is_some();
    let has_operation_source = !request.source_ids.is_empty();
    let mut witness_ids = Vec::new();
    if !has_close_policy {
        witness_ids.push(case_space.case_space_id.clone());
    }
    if !has_operation_source {
        witness_ids.push(case_space.revision.revision_id.clone());
    }
    let Some(gate) = &request.operation_gate else {
        witness_ids.push(case_space.case_space_id.clone());
        return close_invariant(
            "close:native-policy-capability-gate",
            dedupe_ids(witness_ids),
            "Close checks must include an operation gate with actor, capability, scope, audience, and source boundary.",
        );
    };
    if let Err(error) = check_operation_gate(case_space, gate, "close-check") {
        witness_ids.extend(error.witness_ids);
    }
    close_invariant(
        "close:native-policy-capability-gate",
        dedupe_ids(witness_ids),
        "Close checks must name a close policy, source evidence, and a matching operation gate for actor, capability, scope, audience, and source boundary.",
    )
}
